import 'package:flutter/material.dart';
import 'package:souq_skills/core/app_routes.dart';
class AppBottomNavigation extends StatelessWidget { const AppBottomNavigation({required this.index, required this.onChanged, super.key}); final int index; final ValueChanged<int> onChanged; @override Widget build(BuildContext context) => NavigationBar(selectedIndex: index, onDestinationSelected: onChanged, destinations: const [NavigationDestination(icon: Icon(Icons.home_outlined), label: 'Home'), NavigationDestination(icon: Icon(Icons.chat_outlined), label: 'Chats'), NavigationDestination(icon: Icon(Icons.add_circle_outline), label: 'Post'), NavigationDestination(icon: Icon(Icons.account_balance_wallet_outlined), label: 'Wallet'), NavigationDestination(icon: Icon(Icons.person_outline), label: 'Profile')]); static String routeForIndex(int value) => [AppRoutes.home, AppRoutes.chats, AppRoutes.postSkill, AppRoutes.wallet, AppRoutes.profile][value.clamp(0, 4)]; }
